typedef struct Edge {
    int to, rev, cap;
} Edge;

typedef struct {
    Edge *data;
    int size, cap;
} Vec;

static void vec_init(Vec *v) {
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, Edge e) {
    if (v->size == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->data = (Edge *)realloc(v->data, sizeof(Edge) * v->cap);
    }
    v->data[v->size++] = e;
}

static void add_edge(Vec *g, int u, int v, int c) {
    Edge a = {v, g[v].size, c};
    Edge b = {u, g[u].size, 0};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

static int bfs(Vec *g, int n, int s, int t, int *level) {
    int *q = (int *)malloc(sizeof(int) * n);
    int head = 0, tail = 0;
    for (int i = 0; i < n; i++) level[i] = -1;
    level[s] = 0;
    q[tail++] = s;

    while (head < tail) {
        int v = q[head++];
        for (int i = 0; i < g[v].size; i++) {
            Edge *e = &g[v].data[i];
            if (e->cap > 0 && level[e->to] < 0) {
                level[e->to] = level[v] + 1;
                q[tail++] = e->to;
            }
        }
    }
    int ok = (level[t] >= 0);
    free(q);
    return ok;
}

static int dfs(Vec *g, int v, int t, int f, int *level, int *it) {
    if (v == t) return f;
    for (; it[v] < g[v].size; it[v]++) {
        Edge *e = &g[v].data[it[v]];
        if (e->cap > 0 && level[v] < level[e->to]) {
            int d = dfs(g, e->to, t, f < e->cap ? f : e->cap, level, it);
            if (d > 0) {
                e->cap -= d;
                g[e->to].data[e->rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

static int maxflow(Vec *g, int n, int s, int t) {
    int flow = 0;
    int *level = (int *)malloc(sizeof(int) * n);
    int *it = (int *)malloc(sizeof(int) * n);

    while (bfs(g, n, s, t, level)) {
        for (int i = 0; i < n; i++) it[i] = 0;
        while (1) {
            int f = dfs(g, s, t, 1 << 30, level, it);
            if (f == 0) break;
            flow += f;
        }
    }

    free(level);
    free(it);
    return flow;
}

static int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

