        int flow = 0, inf = 1e9;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            int f;
            while ((f = dfs(s, t, inf)) > 0) flow += f;
        }
        return flow;
    }
};

vector<int> prime_factors(int n) {
    vector<int> res;
    for (int p = 2; p * p <= n; ++p) {
        if (n % p == 0) {
            res.push_back(p);
            while (n % p == 0) n /= p;
        }
    }
    if (n > 1) res.push_back(n);
    return res;
}

