import java.util.*;

/*
Maximum bipartite matching:
- Left side: blue cards
- Right side: red cards
- Edge exists if gcd(blue[i], red[j]) > 1

For each dataset:
1) Read B and R
2) Read blue values and red values
3) Build graph
4) Run Hopcroft-Karp
5) Output maximum matching

Input format assumed:
Multiple datasets, each:
  B R
  B integers
  R integers
Terminated by:
  0 0
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class HopcroftKarp {
        int nLeft, nRight;
        ArrayList<Integer>[] g;
        int[] dist, pairU, pairV;

        @SuppressWarnings("unchecked")
        HopcroftKarp(int nLeft, int nRight) {
            this.nLeft = nLeft;
            this.nRight = nRight;
            g = new ArrayList[nLeft];
            for (int i = 0; i < nLeft; i++) g[i] = new ArrayList<>();
            dist = new int[nLeft];
            pairU = new int[nLeft];
            pairV = new int[nRight];
            Arrays.fill(pairU, -1);
            Arrays.fill(pairV, -1);
        }

        void addEdge(int u, int v) {
            g[u].add(v);
        }

        boolean bfs() {
            ArrayDeque<Integer> q = new ArrayDeque<>();
            for (int u = 0; u < nLeft; u++) {
                if (pairU[u] == -1) {
                    dist[u] = 0;
                    q.add(u);
                } else {
                    dist[u] = -1;
                }
            }

            boolean found = false;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : g[u]) {
                    int pu = pairV[v];
                    if (pu == -1) {
                        found = true;
                    } else if (dist[pu] == -1) {
                        dist[pu] = dist[u] + 1;
                        q.add(pu);
                    }
                }
            }
            return found;
        }

        boolean dfs(int u) {
            for (int v : g[u]) {
                int pu = pairV[v];
                if (pu == -1 || (dist[pu] == dist[u] + 1 && dfs(pu))) {
                    pairU[u] = v;
                    pairV[v] = u;
                    return true;
                }
            }
            dist[u] = -1;
            return false;
        }

        int maxMatching() {
            int matching = 0;
            while (bfs()) {
                for (int u = 0; u < nLeft; u++) {
                    if (pairU[u] == -1 && dfs(u)) matching++;
                }
            }
            return matching;
        }
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int b;
            try {
                b = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            int r = fs.nextInt();

            if (b == 0 && r == 0) break;

            int[] blue = new int[b];
            int[] red = new int[r];

            for (int i = 0; i < b; i++) blue[i] = fs.nextInt();
            for (int i = 0; i < r; i++) red[i] = fs.nextInt();

            HopcroftKarp hk = new HopcroftKarp(b, r);

            for (int i = 0; i < b; i++) {
                for (int j = 0; j < r; j++) {
                    if (gcd(blue[i], red[j]) > 1) {
                        hk.addEdge(i, j);
                    }
                }
            }

            out.append(hk.maxMatching()).append('\n');
        }

        System.out.print(out.toString());
    }
}

