class BipartiteMatching:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v):
        self.graph[u].append(v)

    def bfs(self):
        dist = [-1] * self.n
        q = deque()
        for u in range(self.n):
            if self.pair_u[u] == -1:
                dist[u] = 0
                q.append(u)
        found = False
        while q:
            u = q.popleft()
            for v in self.graph[u]:
                if self.pair_v[v] != -1 and dist[self.pair_v[v]] == -1:
                    dist[self.pair_v[v]] = dist[u] + 1
                    q.append(self.pair_v[v])
                elif self.pair_v[v] == -1:
                    found = True
        return found, dist

    def dfs(self, u, dist):
        for v in self.graph[u]:
            if self.pair_v[v] == -1 or (dist[self.pair_v[v]] == dist[u] + 1 and self.dfs(self.pair_v[v], dist)):
                self.pair_u[u] = v
                self.pair_v[v] = u
                return True
        dist[u] = -1
        return False

    def max_matching(self):
        self.pair_u = [-1] * self.n
        self.pair_v = [-1] * self.m
        matching = 0
        while True:
            found, dist = self.bfs()
            if not found:
                break
            for u in range(self.n):
                if self.pair_u[u] == -1:
                    if self.dfs(u, dist):
                        matching += 1
        return matching

