import sys
from collections import deque

# Dinic's max flow
class Edge:
    __slots__ = ("to", "cap", "rev")
    def __init__(self, to, cap, rev):
        self.to = to
        self.cap = cap
        self.rev = rev

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = Edge(to, cap, len(self.g[to]))
        rev = Edge(fr, 0, len(self.g[fr]))
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def max_flow(self, s, t):
        flow = 0
        n = self.n
        INF = 10**18

        while True:
            level = [-1] * n
            q = deque([s])
            level[s] = 0
            while q:
                v = q.popleft()
                for e in self.g[v]:
                    if e.cap > 0 and level[e.to] < 0:
                        level[e.to] = level[v] + 1
                        q.append(e.to)
            if level[t] < 0:
                return flow

            it = [0] * n

            def dfs(v, f):
                if v == t:
                    return f
                for i in range(it[v], len(self.g[v])):
                    it[v] = i
                    e = self.g[v][i]
                    if e.cap > 0 and level[v] < level[e.to]:
                        d = dfs(e.to, min(f, e.cap))
                        if d > 0:
                            e.cap -= d
                            self.g[e.to][e.rev].cap += d
                            return d
                it[v] += 1
                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve_dataset(blue, red):
    n = len(blue)
    m = len(red)
    s = 0
    t = n + m + 1
    mf = Dinic(t + 1)

    for i in range(n):
        mf.add_edge(s, 1 + i, 1)
    for j in range(m):
        mf.add_edge(1 + n + j, t, 1)

    for i in range(n):
        bi = blue[i]
        for j in range(m):
            if gcd(bi, red[j]) > 1:
                mf.add_edge(1 + i, 1 + n + j, 1)

    return mf.max_flow(s, t)

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    out = []
    p = 0

    # Supports common multi-dataset formats:
    # 1) n m, then n blues, then m reds, repeated, ending with 0 0
    # 2) T first, then T datasets of the above form
    #
    # We first try format (1). If it doesn't consume cleanly, fall back to (2).

    def parse_without_t(arr):
        res = []
        i = 0
        while i < len(arr):
            if i + 1 >= len(arr):
                return None
            n, m = arr[i], arr[i + 1]
            i += 2
            if n == 0 and m == 0:
                if i != len(arr):
                    # allow trailing spaces only, but not extra ints
                    return None
                return res
            if i + n + m > len(arr):
                return None
            blue = arr[i:i+n]
            i += n
            red = arr[i:i+m]
            i += m
            res.append((blue, red))
        return res

    parsed = parse_without_t(data)

    if parsed is None:
        T = data[0]
        p = 1
        for _ in range(T):
            n, m = data[p], data[p + 1]
            p += 2
            blue = data[p:p+n]
            p += n
            red = data[p:p+m]
            p += m
            out.append(str(solve_dataset(blue, red)))
    else:
        for blue, red in parsed:
            out.append(str(solve_dataset(blue, red)))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
